\label{lem:saito-stabilized}
Let $X$ be a simple module with $\varepsilon_i^*(X)=0$.
For every integer $s\geq\varphi_i(X)$, one has
\begin{equation}\label{eq:saito-stabilized}
 T_iX=\widetilde E_i^{\,s-\langle h_i,\operatorname{wt}(X)\rangle}
               (\widetilde F_i^*)^sX.
\end{equation}

\label{lem:truncated-weave-mutations}
Let $\mathfrak U$ be a truncated double inductive weave with
vertex set $S$, and let $\mathfrak W$ be obtained by restoring
the remaining insertions, with vertex set $K\supseteq S$.
For every vertex $t$ mutable in $\mathfrak U$,
\begin{equation}\label{eq:truncated-weave-exchange}
 b^{\mathfrak W}_{zt}
 =\begin{cases}
    b^{\mathfrak U}_{zt},&z\in S,\\
    0,&z\in K\setminus S.
   \end{cases}
\end{equation}
Every mutation sequence in the truncated weave extends to
the full weave with the same exchange monomials.
The variables at the additional vertices remain unchanged.

\label{thm:determinantial-factorization}
For $1\leq k\leq r$ and $\Lambda\in P_+$, there is an isomorphism
\begin{equation}\label{eq:dominant-determinantial-factors}
 M(w_{\leq k}\Lambda,v_{\leq k}\Lambda)
 \simeq
 \bigodot_{\substack{u\in V_{\mathbf{w},v}\\q_u\leq k}}
       M_u^{\odot m_{u,k}(\Lambda)}.
\end{equation}
In particular, for every $j\in I$,
\begin{equation}\label{eq:determinantial-factors}
 M(w_{\leq k}\varpi_j,v_{\leq k}\varpi_j)
 \simeq
 \bigodot_{\substack{u\in V_{\mathbf{w},v}\\q_u\leq k}}
       M_u^{\odot m_{u,k}^{\,j}}.
\end{equation}

\label{cor:multiplicity-from-parameters}
For $1\leq k\leq r$, $j\in I$, and $u\in V_{\mathbf{w},v}$ with
$q_u\leq k$, the multiplicity in
Theorem~\ref{thm:determinantial-factorization} is
\begin{equation}\label{eq:multiplicity-from-parameters}
 m_{u,k}^{\,j}
 =(\boldsymbol{\delta}_{k,j})_{q_u}
  -\sum_{\substack{x>u\\q_x\leq k}}
       \gamma_u(e_{x,\mathrm{nw}})(\boldsymbol{\delta}_{k,j})_{q_x}.
\end{equation}
The same formula holds for $m_{u,k}(\Lambda)$ after replacing
$\boldsymbol{\delta}_{k,j}$ by $\boldsymbol{\delta}_k(\Lambda)$.
